python -c "
import pandas as pd
from pymatgen.core import Composition
train_df = pd.read_csv('nlo_shg_train.csv')
anions = {}
for _, row in train_df.iterrows():
    c = Composition(row['formula'])
    for el in c.elements:
        if el.symbol not in anions:
            anions[el.symbol] = 0
        anions[el.symbol] += 1
for k, v in sorted(anions.items(), key=lambda x: x[1], reverse=True)[:15]:
    print(k, v)
